#!/usr/bin/env python3\n\"\"\"\nTest script for supplier location mapping functionality.\nVerifies that suppliers can be displayed on the dashboard map alongside projects.\n\"\"\"\n\nimport requests\nimport json\n\ndef test_supplier_mapping():\n    \"\"\"Test the complete supplier mapping functionality.\"\"\"\n    \n    print(\"🧪 Testing Supplier Location Mapping\")\n    print(\"=\" * 40)\n    \n    base_url = \"http://localhost:8000\"\n    \n    try:\n        # Test 1: Project locations API\n        print(\"\\n1️⃣ Testing project locations API...\")\n        response = requests.get(f\"{base_url}/api/gis/project-locations\")\n        if response.status_code == 200:\n            projects = response.json()\n            print(f\"   ✅ Found {len(projects)} projects\")\n            for project in projects:\n                if project.get('latitude') and project.get('longitude'):\n                    print(f\"      🏗️ {project['name']}: {project['latitude']:.4f}, {project['longitude']:.4f}\")\n        else:\n            print(f\"   ❌ Project API error: {response.status_code}\")\n            return False\n        \n        # Test 2: Supplier locations API\n        print(\"\\n2️⃣ Testing supplier locations API...\")\n        response = requests.get(f\"{base_url}/api/gis/supplier-locations\")\n        if response.status_code == 200:\n            suppliers = response.json()\n            print(f\"   ✅ Found {len(suppliers)} suppliers\")\n            for supplier in suppliers:\n                if supplier.get('latitude') and supplier.get('longitude'):\n                    print(f\"      🏪 {supplier['name']}: {supplier['latitude']:.4f}, {supplier['longitude']:.4f}\")\n        else:\n            print(f\"   ❌ Supplier API error: {response.status_code}\")\n            return False\n        \n        # Test 3: Dashboard accessibility\n        print(\"\\n3️⃣ Testing dashboard accessibility...\")\n        response = requests.get(f\"{base_url}/\")\n        if response.status_code == 200:\n            print(\"   ✅ Dashboard accessible\")\n            \n            # Check if dashboard contains map elements\n            content = response.text\n            if 'projects-map' in content:\n                print(\"   ✅ Map container found in dashboard\")\n            else:\n                print(\"   ❌ Map container not found\")\n                \n            if 'loadAllMarkers' in content:\n                print(\"   ✅ Supplier loading function found\")\n            else:\n                print(\"   ❌ Supplier loading function not found\")\n                \n        else:\n            print(f\"   ❌ Dashboard error: {response.status_code}\")\n            return False\n        \n        print(\"\\n🎉 All supplier mapping tests passed!\")\n        print(\"\\n📋 Summary:\")\n        print(f\"   • Projects with coordinates: {len([p for p in projects if p.get('latitude')])}\") \n        print(f\"   • Suppliers with coordinates: {len([s for s in suppliers if s.get('latitude')])}\")\n        print(f\"   • Dashboard map integration: ✅\")\n        print(f\"   • API endpoints working: ✅\")\n        \n        print(\"\\n🗺️ You can now view the dashboard at: http://localhost:8000\")\n        print(\"   The map should show both projects (circles) and suppliers (diamonds)\")\n        \n        return True\n        \n    except requests.exceptions.ConnectionError:\n        print(\"❌ Connection error: Make sure the server is running on port 8000\")\n        return False\n    except Exception as e:\n        print(f\"❌ Unexpected error: {e}\")\n        return False\n\nif __name__ == \"__main__\":\n    success = test_supplier_mapping()\n    if not success:\n        exit(1)\n"